    /// amount to automatically grant users upon first login to the title
    /// </summary>
    [JsonPropertyName("InitialDeposit")]
    public double? InitialDeposit { get; set; }

    /// <summary>
    /// maximum amount to which the currency will recharge (cannot exceed MaxAmount, but can be less)
    /// </summary>
    [JsonPropertyName("RechargeMax")]
    public double? RechargeMax { get; set; }

    /// <summary>
    /// rate at which the currency automatically be added to over time, in units per day (24 hours)
    /// </summary>
    [JsonPropertyName("RechargeRate")]
    public double? RechargeRate { get; set; }

}

public sealed class VirtualCurrencyRechargeTime
{
    /// <summary>
    /// Maximum value to which the regenerating currency will automatically increment. Note that it can exceed this value through use of the AddUserVirtualCurrency API call. However, it will not regenerate automatically until it has fallen below this value.
    /// </summary>
    [JsonPropertyName("RechargeMax")]
    public double RechargeMax { get; set; }

    /// <summary>
    /// Server timestamp in UTC indicating the next time the virtual currency will be incremented.
    /// </summary>
    [JsonPropertyName("RechargeTime")]
    public string? RechargeTime { get; set; }

    /// <summary>
    /// Time remaining (in seconds) before the next recharge increment of the virtual currency.
    /// </summary>
    [JsonPropertyName("SecondsToRecharge")]
    public double SecondsToRecharge { get; set; }

}
